export function legalMoves(puzzle, pegs) {
  const pegSet = new Set(pegs);
  const cells = new Set(puzzle.cells);
  const moves = [];
  for (const from of pegs) {
    const [fx, fy] = from.split(',').map(Number);
    for (const [dx, dy] of puzzle.directions) {
      const ox = fx + dx, oy = fy + dy;
      const tx = fx + 2 * dx, ty = fy + 2 * dy;
      const over = `${ox},${oy}`;
      const to = `${tx},${ty}`;
      if (cells.has(from) && cells.has(over) && cells.has(to) && pegSet.has(over) && !pegSet.has(to)) {
        moves.push([from, over, to]);
      }
    }
  }
  return moves;
}

export function applyMove(puzzle, pegs, move) {
  const legal = legalMoves(puzzle, pegs);
  const match = legal.find(m => m[0] === move[0] && m[1] === move[1] && m[2] === move[2]);
  if (!match) throw new Error('Illegal move');
  const [from, over] = move;
  return pegs.filter(p => p !== from && p !== over).concat(move[2]);
}

export function isSolved(puzzle, pegs) {
  if (pegs.length !== puzzle.goal.length) return false;
  const goalSet = new Set(puzzle.goal);
  for (const p of pegs) {
    if (!goalSet.has(p)) return false;
  }
  return true;
}

